// Edge split E2 (plan §C) — "Edge Inbound: build CALL" function node.
// IN:  mqtt-in on topic  mis/edge/+/cycle  (ESP32 edge envelope)
// OUT: a mysql node (config "Edge Outbox", fc9634aabefee16b) running edge_inbound_ingest
//
// Parses the ESP32 envelope and prepares the atomic dedup/ack proc call. Carries
// level/tsDevice forward on msg for the ack+forward node.

let env = msg.payload;
if (typeof env === "string") {
    try { env = JSON.parse(env); } catch (e) { node.warn("edge inbound: bad JSON"); return null; }
}
if (!env || typeof env !== "object") { node.warn("edge inbound: empty"); return null; }

const machineId = env.machineId;
const seq = Number(env.seq);
const p = env.payload || {};
const channel = Number(p.channel ?? 0);
const level = Number(p.level);
const tsDevice = Number(env.tsDevice ?? p.tsDevice);   // absolute UTC ms from the ESP32
const clockSynced = p.clockSynced === true ? 1 : 0;

if (!machineId || !Number.isFinite(seq) || (level !== 0 && level !== 1) || !Number.isFinite(tsDevice)) {
    node.warn("edge inbound: invalid envelope " + JSON.stringify(env).slice(0, 120));
    return null;
}

// Stash for the ack+forward node (mysql result won't echo these).
msg._edge = { machineId, seq, channel, level, tsDevice, clockSynced };

msg.topic = "CALL edge_inbound_ingest(?, ?, ?, ?, ?, ?);";
msg.payload = [machineId, seq, channel, level, tsDevice, clockSynced];
return msg;

// Edge split E2 (plan §C) — "Edge Inbound: ack + forward" function node.
// IN:  the mysql node result of edge_inbound_ingest  → { is_new, ack_seq }
// OUT 1 (top): → existing "function 1" (d8b64d16026af66d) — ONLY when the edge is new
// OUT 2 (bot): → mqtt-out, topic mis/edge/<id>/ack — ALWAYS (so the ESP32 can trim)
//
// The forwarded message mimics the old rpi-gpio output: msg.payload = level (0/1),
// plus msg.tsDevice (absolute UTC) and msg.machineId for the device-time logic (E3).

const e = msg._edge || {};

// Parse { is_new, ack_seq } from the CALL result (mysql returns nested arrays for CALL).
let isNew = null, ackSeq = null;
const res = msg.payload;
if (Array.isArray(res)) {
    const row = (Array.isArray(res[0]) ? res[0][0] : res[0]) || {};
    if (row.is_new != null) isNew = Number(row.is_new);
    if (row.ack_seq != null) ackSeq = Number(row.ack_seq);
}

// Always ack the high-water seq so the ESP32 can drain its flash buffer.
let ackMsg = null;
if (e.machineId && ackSeq != null) {
    ackMsg = {
        topic: "mis/edge/" + e.machineId + "/ack",
        payload: JSON.stringify({ ackSeq: ackSeq }),
    };
}

// Forward into the cycle pipeline only for a genuinely new edge (dedup gate).
let fwd = null;
if (isNew === 1) {
    fwd = {
        payload: e.level,          // function 1 does Number(msg.payload)
        tsDevice: e.tsDevice,      // absolute UTC ms — Machine cycles uses this (E3)
        machineId: e.machineId,
        clockSynced: e.clockSynced === 1,
    };
}

node.status({ fill: isNew === 1 ? "green" : "grey", shape: "dot",
              text: "seq " + (e.seq ?? "?") + (isNew === 1 ? " new" : " dup") + " ack " + (ackSeq ?? "?") });
return [fwd, ackMsg];

// Edge split E2 (plan §E) — "Clock responder" function node.
// IN:  mqtt-in on topic  mis/edge/+/time/req   ({ machineId, reqDeviceMs })
// OUT: mqtt-out — topic mis/edge/<id>/time      ({ reqDeviceMs, piUtcMs })
//
// The ESP32 has no RTC. It sends its monotonic reqDeviceMs; we echo it with the
// Pi's current UTC so the ESP32 can compute offset = piUtcMs + RTT/2 - recvDeviceMs.
// IMPORTANT: the Pi's own clock must be NTP-synced (P6.4) for this to be correct —
// the consistency health check surfaces both clocks (plan §E).

let req = msg.payload;
if (typeof req === "string") {
    try { req = JSON.parse(req); } catch (e) { return null; }
}
if (!req || !req.machineId) return null;

return {
    topic: "mis/edge/" + req.machineId + "/time",
    payload: JSON.stringify({
        reqDeviceMs: Number(req.reqDeviceMs) || 0,
        piUtcMs: Date.now(),
    }),
};

// Edge split E4 (plan §D) — "Reader liveness: record" function node.
// IN: mqtt-in on topic  mis/edge/+/heartbeat  (ESP32 reader_heartbeat)
// OUT: none (sets globals consumed by the evaluate timer + Online HeartBeat).
//
// Records the freshness + health of the wireless reader on every reader heartbeat.
// The "evaluate" timer turns this into the readerOnline boolean (it must go false
// when heartbeats STOP, which only a timer can detect).

let hb = msg.payload;
if (typeof hb === "string") { try { hb = JSON.parse(hb); } catch (e) { return null; } }
if (!hb || typeof hb !== "object") return null;
const p = hb.payload || {};

global.set("readerLastSeenMs", Date.now());
if (typeof p.clockSynced === "boolean") global.set("readerClockSynced", p.clockSynced);
if (typeof p.bufferDepth === "number") global.set("readerBufferDepth", p.bufferDepth);
return null;

// Edge split E4 (plan §D) — "Reader liveness: evaluate" function node.
// IN:  an inject node, every 5s (repeat). OUT: none (sets global readerOnline).
//
// Turns reader-heartbeat freshness into the readerOnline boolean that BOTH the
// Anomaly Detector (suppresses false stoppages when false) and the Online
// HeartBeat (reports DATA_LOSS to the cloud) read. Runs on a timer so the link
// is marked dead when heartbeats STOP, not only when a message arrives.
//
// STALE threshold = 3x the ESP32 heartbeat cadence (CFG_HEARTBEAT_MS=5s) = 15s.

const STALE_MS = 15000;
const lastSeen = Number(global.get("readerLastSeenMs") || 0);

// Until the first reader heartbeat ever arrives, leave readerOnline UNSET (null →
// "not a split machine / not reported"), so non-split machines never show DATA_LOSS.
if (lastSeen === 0) return null;

const online = (Date.now() - lastSeen) <= STALE_MS;
global.set("readerOnline", online);
node.status({ fill: online ? "green" : "red", shape: online ? "dot" : "ring",
              text: online ? "reader online" : "DATA_LOSS: reader dead" });
return null;
